function cx(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(' '); }
function money(value?: number | null) { return typeof value === 'number' ? `$${value.toFixed(2)}` : '—'; }
function compact(value?: number | null) {
  if (typeof value !== 'number') return '—';
  return new Intl.NumberFormat('en-US', { notation: 'compact', maximumFractionDigits: 1 }).format(value);
}
function initials(value = 'AS') { return value.split(/\s+/).slice(0, 2).map((x) => x[0]).join('').toUpperCase(); }

function RouteMeta() {
  const [location] = useLocation();
  useEffect(() => {
    const basePath = location.startsWith('/products/') || location.startsWith('/sellers/') ? location.split('/').slice(0, 2).join('/') : location.split('?')[0] || '/';
    const fallback = routeMeta[basePath] || { title: 'AmazonScope | Amazon product intelligence', description: 'Amazon marketplace intelligence for sharper product decisions.' };
    document.title = fallback.title;
    const setMeta = (selector: string, attribute: string, content: string) => {
      const node = document.head.querySelector(selector) as HTMLMetaElement | null;
      if (node) node.setAttribute(attribute, content);
    };
    setMeta('meta[name="description"]', 'content', fallback.description);
    setMeta('meta[property="og:title"]', 'content', fallback.title);
    setMeta('meta[property="og:description"]', 'content', fallback.description);
    setMeta('meta[name="twitter:title"]', 'content', fallback.title);
    setMeta('meta[name="twitter:description"]', 'content', fallback.description);
    setMeta('meta[property="og:url"]', 'content', window.location.href);
    let canonical = document.head.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
    if (!canonical) {
      canonical = document.createElement('link');
      canonical.rel = 'canonical';
      document.head.appendChild(canonical);
    }
    canonical.href = window.location.href.split('?')[0];
  }, [location]);
  return null;
}

