function isNavActive(location: string, href: string) {
  if (href === '/overview') return location === '/overview' || location === '/';
  if (href === '/sellers') return location === '/sellers' || location.startsWith('/sellers/');
  if (href === '/best-sellers') return location === '/best-sellers';
  if (href === '/checker') return location === '/checker' || location.startsWith('/products/');
  return location === href || location.startsWith(href + '/');
}

