  const creator = ({ name: 'Maya Chen', handle: '@mayamakes', followers: 284000, platform: 'YouTube', ...(profile.data as any || {}) }) as any;
  const postList = ((posts.data as any)?.posts || [{ id: 'p1', title: 'The desk setup that finally works', publishedAt: '2 days ago', engagementRate: 8.4 }, { id: 'p2', title: 'Five kitchen tools earning their keep', publishedAt: '1 week ago', engagementRate: 6.8 }, { id: 'p3', title: 'Small upgrades, big daily difference', publishedAt: '2 weeks ago', engagementRate: 5.9 }]) as any[];
  return <div className="mx-auto max-w-[1180px] space-y-7"><SectionHeading eyebrow="Creator intelligence" title="Influencers" detail="See who is shaping category demand and which products travel with them." /><Panel className="p-5 sm:p-7"><div className="flex flex-wrap items-center gap-4"><div className="grid size-16 place-items-center rounded-2xl bg-secondary font-[var(--app-font-mono)] text-xl font-bold text-primary">{initials(creator.name)}</div><div className="flex-1"><div className="text-[10px] font-bold uppercase tracking-[.18em] text-primary">{creator.platform}</div><h2 className="mt-1 font-[var(--app-font-mono)] text-2xl font-bold">{creator.name}</h2><div className="text-sm text-muted-foreground">{creator.handle}</div></div><div className="text-left sm:text-right"><div className="font-[var(--app-font-mono)] text-2xl font-bold">{compact(creator.followers)}</div><div className="text-xs text-muted-foreground">followers</div></div></div><div className="mt-6 grid gap-3 sm:grid-cols-3"><MiniMetric label="Avg. engagement" value="7.2%" trend="+1.4%" icon={Activity} /><MiniMetric label="Tagged products" value="86" trend="14 rising" icon={Tag} /><MiniMetric label="Category focus" value="Home" icon={Layers3} /></div></Panel><div className="grid gap-5 md:grid-cols-3">{postList.map((post) => <article key={post.id} className="group rounded-2xl border border-border bg-card p-4 hover-elevate" data-testid={`card-influencer-post-${post.id}`}><div className="mb-5 flex h-32 items-end rounded-xl bg-[linear-gradient(135deg,#e5f0ee,#f1dec1)] p-3"><span className="font-[var(--app-font-mono)] text-4xl font-bold text-primary/20">/{creator.platform?.slice(0, 2)}</span></div><div className="text-[10px] font-bold uppercase tracking-[.15em] text-primary">{post.publishedAt}</div><h3 className="mt-2 font-[var(--app-font-mono)] text-base font-bold leading-5">{post.title}</h3><div className="mt-4 flex items-center justify-between text-xs text-muted-foreground"><span>{post.engagementRate}% engagement</span><button className="text-primary" data-testid={`button-open-post-${post.id}`}><ExternalLink size={14} /></button></div></article>)}</div></div>;
